.attr-line{
  padding-left: 20px;
  span{
    padding: 0;
  }
}
.jijijiji{
  position: relative;
  &::before{
    content: '';
    position: absolute;
    left: 32px;
    width: 0px;
    height: 6px;
    border-left: 1px solid;
    z-index: 9;
    margin-right: 4px;
    color: #409EFF;
  }
  &::after{
    content: '';
    position: absolute;
    left: 32px;
    bottom: 0;
    width: 0px;
    height: 6px;
    border-left: 1px solid;
    z-index: 9;
    margin-right: 4px;
    color: #409EFF;
  }
}

.parent-item{
  position: relative;
}
.postionFix {
  position: absolute;
  top: -20px;
  right: 0;
  font-size: 15px;
  cursor: pointer;
}
.el-dropdown-link{
  cursor: pointer;
  color: #409EFF;
}
.isActive{
  color: #409EFF;
}
::v-deep .ruleCon_Con{
  overflow: hidden;
  .el-col{
    margin-bottom: 0;
  }
}
.ruleCon_item{
